{"content":""""Sokoban puzzle solver using A* search over pushes.

Reads the puzzle from /app/puzzle.txt and writes /app/solution.json
as {"moves": "UDLR..."}.

Standard library only (collections, json, heapq, time).
"""

import json
import heapq
import time
from collections import deque

DIRS = {
    'U': (-1, 0),
    'D': (1, 0),
    'L': (0, -1),
    'R': (0, 1),
}
DIR_ORDER = ('U', 'D', 'L', 'R')
INF = 10 ** 9


def parse_puzzle(filename):
    """Read puzzle file and return puzzle string."""
    with open(filename, 'r') as f:
        return f.read()


def parse_map(puzzle_str):
    """Parse Sokoban map symbols and extract game state.

    Returns (player_pos, boxes, targets, walls).
    """
    lines = puzzle_str.splitlines()
    while lines and lines[-1] == '':
        lines.pop()
    if not lines:
        return (None, set(), set(), set())
    width = max(len(line) for line in lines)
    if width == 0:
        return (None, set(), set(), set())
    player_pos = None
    boxes = set()
    targets = set()
    walls = set()
    for r, line in enumerate(lines):
        for c in range(width):
            # Short rows are padded with walls (outside the level).
            ch = line[c] if c < len(line) else '#'
            pos = (r, c)
            if ch == '#':
                walls.add(pos)
            elif ch == '@':
                player_pos = pos
            elif ch == '+':
                player_pos = pos
                targets.add(pos)
            elif ch == '$':
                boxes.add(pos)
            elif ch == '*':
                boxes.add(pos)
                targets.add(pos)
            elif ch == '.':
                targets.add(pos)
            else:
                # ' ' (empty floor) or anything unknown: walkable floor.
                pass
    return (player_pos, boxes, targets, walls)


def try_move(player_pos, boxes, walls, direction):
    """Attempt to move player in the given direction.

    Returns (new_player_pos, new_boxes) if valid, None if invalid.
    """
    if direction not in DIRS:
        return None
    dr, dc = DIRS[direction]
    new_player = (player_pos[0] + dr, player_pos[1] + dc)
    if new_player in walls:
        return None
    if new_player in boxes:
        new_box = (new_player[0] + dr, new_player[1] + dc)
        if new_box in walls or new_box in boxes:
            return None
        new_boxes = set(boxes)
        new_boxes.discard(new_player)
        new_boxes.add(new_box)
        return (new_player, new_boxes)
    return (new_player, set(boxes))


def _grid_dims(puzzle_str):
    lines = puzzle_str.splitlines()
    while lines and lines[-1] == '':
        lines.pop()
    if not lines:
        return (0, 0)
    return (len(lines), max(len(line) for line in lines))


def _compute_static_dead(walls, targets, rows, cols):
    """Cells (non-wall, non-target) from which a box can never reach a target.

    Reverse pull analysis using walls only: from every target, a box could
    have come from `frm = to - d` if both `frm` and the pushing cell
    `frm - d` are free of walls. Cells never marked live are dead. This is
    sound: if a box cannot reach a target even with no other boxes around,
    it never will.
    """
    def is_wall(p):
        return not (0 <= p[0] < rows and 0 <= p[1] < cols) or p in walls

    live = set(targets)
    queue = deque(targets)
    while queue:
        t = queue.popleft()
        for dr, dc in DIRS.values():
            frm = (t[0] - dr, t[1] - dc)
            need = (t[0] - 2 * dr, t[1] - 2 * dc)
            if frm in live or is_wall(frm) or is_wall(need):
                continue
            live.add(frm)
            queue.append(frm)
    dead = set()
    for r in range(rows):
        for c in range(cols):
            p = (r, c)
            if p in walls or p in targets:
                continue
            if p not in live:
                dead.add(p)
    return dead


def _maze_distances(walls, targets, rows, cols):
    """Shortest wall-avoiding distance from each target to every cell."""
    dists = []
    for t in sorted(targets):
        dist = {t: 0}
        queue = deque([t])
        while queue:
            cur = queue.popleft()
            for dr, dc in DIRS.values():
                nxt = (cur[0] + dr, cur[1] + dc)
                if not (0 <= nxt[0] < rows and 0 <= nxt[1] < cols):
                    continue
                if nxt in walls or nxt in dist:
                    continue
                dist[nxt] = dist[cur] + 1
                queue.append(nxt)
        dists.append(dist)
    return dists


def _hungarian(cost):
    """Minimum assignment cost for a square matrix (Kuhn-Munkres)."""
    n = len(cost)
    u = [0] * (n + 1)
    v = [0] * (n + 1)
    p = [0] * (n + 1)
    way = [0] * (n + 1)
    for i in range(1, n + 1):
        p[0] = i
        j0 = 0
        minv = [float('inf')] * (n + 1)
        used = [False] * (n + 1)
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = float('inf')
            j1 = 0
            for j in range(1, n + 1):
                if used[j]:
                    continue
                cur = cost[i0 - 1][j - 1] - u[i0] - v[j]
                if cur < minv[j]:
                    minv[j] = cur
                    way[j] = j0
                if minv[j] < delta:
                    delta = minv[j]
                    j1 = j
            for j in range(n + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while j0:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
    return -v[0]


def _reachable_parents(player_pos, boxes, walls):
    """BFS from player over free cells; returns {cell: (prev, move)}."""
    parents = {player_pos: None}
    queue = deque([player_pos])
    while queue:
        cur = queue.popleft()
        for move in DIR_ORDER:
            dr, dc = DIRS[move]
            nxt = (cur[0] + dr, cur[1] + dc)
            if nxt in walls or nxt in boxes or nxt in parents:
                continue
            parents[nxt] = (cur, move)
            queue.append(nxt)
    return parents


def _path_to(parents, start, cell):
    """Reconstruct move string from start to cell using BFS parent map."""
    if cell == start:
        return ''
    if cell not in parents:
        return None
    moves = []
    cur = cell
    while cur != start:
        prev = parents.get(cur)
        if prev is None:
            return None
        cur, move = prev
        moves.append(move)
    moves.reverse()
    return ''.join(moves)


def _simulate(player_pos, boxes, walls, targets, moves):
    """Verify a move string solves the puzzle. Returns True/False."""
    player = player_pos
    cur_boxes = set(boxes)
    for move in moves:
        res = try_move(player, cur_boxes, walls, move)
        if res is None:
            return False
        player, cur_boxes = res
    return cur_boxes == set(targets)


def solve(puzzle_str, time_limit=15.0, max_expansions=None):
    """Solve a Sokoban puzzle with A* search over pushes.

    Returns a move sequence string using only UDLR characters, or "" when
    the puzzle is already solved or deemed unsolvable.
    """
    start_time = time.monotonic()
    try:
        player_pos, boxes, targets, walls = parse_map(puzzle_str)
    except Exception:
        return ""
    if player_pos is None:
        return ""
    boxes = set(boxes)
    targets = set(targets)
    walls = set(walls)
    if len(boxes) == 0 or len(targets) == 0:
        return ""
    if len(boxes) != len(targets):
        return ""
    if boxes == targets:
        return ""
    n = len(boxes)

    rows, cols = _grid_dims(puzzle_str)

    if max_expansions is None:
        if n <= 4:
            max_expansions = 400000
        elif n <= 6:
            max_expansions = 250000
        elif n <= 8:
            max_expansions = 120000
        else:
            max_expansions = 40000
    if n >= 9:
        time_limit = min(time_limit, 5.0)
    elif n >= 7:
        time_limit = min(time_limit, 10.0)

    static_dead = _compute_static_dead(walls, targets, rows, cols)
    if boxes & static_dead:
        return ""
    dists = _maze_distances(walls, targets, rows, cols)

    use_hungarian = n <= 6
    h_cache = {}

    def heuristic(frozen_boxes):
        cached = h_cache.get(frozen_boxes)
        if cached is not None:
            return cached
        blist = sorted(frozen_boxes)
        cost = []
        for b in blist:
            row = [dists[j].get(b, INF) for j in range(n)]
            if min(row) >= INF:
                h_cache[frozen_boxes] = INF
                return INF
            cost.append(row)
        if n == 1:
            h = cost[0][0]
        elif use_hungarian:
            h = _hungarian(cost)
            if h >= INF:
                h = INF
        else:
            # Admissible weaker bound: each box to its nearest target.
            h = sum(min(row) for row in cost)
        h_cache[frozen_boxes] = h
        return h

    start_boxes = frozenset(boxes)
    h0 = heuristic(start_boxes)
    if h0 >= INF:
        return ""
    target_set = frozenset(targets)

    heap = [(h0, 0, 0, player_pos, start_boxes)]
    best_g = {(player_pos, start_boxes): 0}
    parent = {}
    expansions = 0
    counter = 0

    while heap:
        if time.monotonic() - start_time > time_limit:
            return ""
        if expansions >= max_expansions:
            return ""
        f, g, _, pl, bx = heapq.heappop(heap)
        key = (pl, bx)
        if best_g.get(key, INF) != g:
            continue
        if bx == target_set:
            segs = []
            cur = key
            while cur in parent:
                prev, seg = parent[cur]
                segs.append(seg)
                cur = prev
            segs.reverse()
            moves = ''.join(segs)
            if _simulate(player_pos, boxes, walls, targets, moves):
                return moves
            return ""
        expansions += 1
        boxset = set(bx)
        parents = _reachable_parents(pl, boxset, walls)
        cands = []
        for b in bx:
            for dch in DIR_ORDER:
                dr, dc = DIRS[dch]
                behind = (b[0] - dr, b[1] - dc)
                dest = (b[0] + dr, b[1] + dc)
                if dest in walls or dest in boxset:
                    continue
                if behind not in parents:
                    continue
                walk = _path_to(parents, pl, behind)
                if walk is None:
                    continue
                if dest in static_dead:
                    continue
                newset = set(boxset)
                newset.discard(b)
                newset.add(dest)
                fb = frozenset(newset)
                h = heuristic(fb)
                if h >= INF:
                    continue
                cands.append((h, b, dest, fb, walk + dch))
        cands.sort(key=lambda item: item[0])
        for h, b, dest, fb, seg in cands:
            nkey = (b, fb)  # player ends on the box's old cell
            ng = g + 1
            if best_g.get(nkey, INF) <= ng:
                continue
            best_g[nkey] = ng
            parent[nkey] = (key, seg)
            counter += 1
            heapq.heappush(heap, (ng + h, ng, counter, b, fb))
    return ""


def main():
    """Read /app/puzzle.txt, solve, write /app/solution.json."""
    try:
        puzzle_str = parse_puzzle('/app/puzzle.txt')
    except Exception:
        puzzle_str = ''
    try:
        moves = solve(puzzle_str)
    except Exception:
        moves = ''
    if not isinstance(moves, str):
        moves = ''
    moves = ''.join(ch for ch in moves.strip().upper() if ch in 'UDLR')
    with open('/app/solution.json', 'w') as f:
        json.dump({'moves': moves}, f)


if __name__ == '__main__':
    main()
